{
  "options": [
    {
      "id": "A",
      "name": "Dynamic PK Substudy Events and Granular Schedule Forms",
      "summary": "Create dedicated dynamic events for the 7 PK substudy visits (V2.1–V8.1) triggered by RAND.PKSUB, add dedicated forms for ADA, Diary, and Physical Exam, and expand existing forms and edit checks for TB, Virology, AESI, and eligibility windows.",
      "pros": [
        "Mirrors the protocol schedule of assessments 1:1 with dedicated visits V2.1, V2.2, V2.3, V7.1, V7.2, V7.3, and V8.1.",
        "Dynamic event rules based on RAND.PKSUB='Yes' prevent PK substudy visits from cluttering the schedule for non-PK subjects.",
        "Dedicated forms for ADA, Diary, and Physical Exam (weight) provide clear visit-level compliance tracking and SDV alignment."
      ],
      "cons": [
        "Increases the total event count in the casebook by 7 visits.",
        "Requires updating existing cross-visit PK edit checks and SDV plans to include the new PK visit IDs."
      ],
      "tradeoff": "This design gives sites a schedule that matches the protocol visit-by-visit and hides PK visits for non-substudy patients. It costs extra build effort to configure seven dynamic events and update cross-visit rules.",
      "recommended": true
    },
    {
      "id": "B",
      "name": "Consolidated Forms on Parent Visits Without Sub-Visits",
      "summary": "Keep the existing 11-visit structure by collecting the 48h, 144h, and 240h PK samples on the parent visits (V2, V7, V8), and embed new items into existing forms where possible rather than creating new events.",
      "pros": [
        "No new events need to be added to the casebook spine.",
        "Existing PK edit checks and review plans remain valid without changing event scopes."
      ],
      "cons": [
        "Forces sites to enter Day 2, Day 6, and Day 10 PK samples inside the Day 0 (V2) or Day 70 (V7) visit folders, which does not match the protocol's visit numbering (V2.1–V8.1).",
        "Harder for monitors and data managers to track missed intermediate PK visits versus missed timepoints on dosing days."
      ],
      "tradeoff": "This approach avoids adding any new visits to the event schedule and keeps rule scopes simple. However, it forces sites to log multi-day PK follow-up samples inside the parent dosing visit folder.",
      "recommended": false
    },
    {
      "id": "C",
      "name": "Static PK Sub-Visits with Form-Level Dynamics",
      "summary": "Add V2.1–V8.1 as static (non-dynamic) scheduled events for all subjects and use dynamic form rules or a 'Not Done' check on the PK form for subjects not in the PK substudy, along with full form additions for new assessments.",
      "pros": [
        "Matches protocol visit labels (V2.1–V8.1) without relying on event-level dynamic rules.",
        "Simple event structure where every subject has the exact same visit matrix."
      ],
      "cons": [
        "Non-PK substudy subjects will show 7 empty or inapplicable PK visits on their subject matrix.",
        "Increases risk of accidental data entry or unnecessary query resolution on PK visits for non-substudy subjects."
      ],
      "tradeoff": "This option aligns with the protocol visit numbering while avoiding complex event-level dynamics. It clutters the casebook matrix with seven blank PK visits for every patient who declines the substudy.",
      "recommended": false
    }
  ]
}
